(function(){
  'use strict';
  let lastView='3d';
  const esc=value=>String(value).replace(/[&<>"']/g,ch=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[ch]));
  const paths={cube:'<path d="m12 3 9 5-9 5-9-5Zm-9 5v10l9 5 9-5V8M12 13v10"/>',play:'<path d="m8 5 11 7-11 7Z"/>',pause:'<path d="M8 5v14M16 5v14"/>',reset:'<path d="M3 11a9 9 0 1 1 2 7M3 5v6h6"/>',plus:'<path d="M5 12h14M12 5v14"/>',minus:'<path d="M5 12h14"/>',expand:'<path d="M8 3H3v5m13-5h5v5M3 16v5h5m13-5v5h-5"/>',top:'<path d="m12 3 9 5-9 5-9-5Zm-9 9 9 5 9-5M3 17l9 5 9-5"/>',close:'<path d="m6 6 12 12M6 18 18 6"/>',link:'<path d="m9 15 6-6m-7 3-2 2a3 3 0 0 0 4 4l2-2m0-8 2-2a3 3 0 0 1 4 4l-2 2"/>',arrow:'<path d="M4 12h16m-6-6 6 6-6 6"/>',rotate:'<path d="M4 9a8 8 0 0 1 14-3l3 3m0-6v6h-6M4 15a8 8 0 0 0 14 3M3 12v6h6"/>',search:'<circle cx="10" cy="10" r="6"/><path d="m15 15 5 5"/>'};
  const icon=name=>'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">'+paths[name]+'</svg>';
  const tool=(action,label,ico)=>'<button type="button" class="scene-tool" data-vaction="'+action+'" aria-label="'+label+'" title="'+label+'">'+icon(ico)+'</button>';
  function panel(props){
    const E=props.engine||window.KbitEngine;
    const counts=Array(E.products.length).fill(0);for(const order of props.orders)for(const id of new Set(order.items))counts[id]++;
    const sectors=props.imported&&E.layout.spec.bays>24?'<label class="scene-sector-select">Sector <select id="scene-sector" aria-label="Sector del almacén importado"><option value="-1">Todo el almacén</option>'+Array.from({length:Math.ceil(E.layout.spec.bays/24)},(_,i)=>'<option value="'+i+'"'+(i===0?' selected':'')+'>Sector '+(i+1)+' · posiciones '+(i*24+1)+'–'+Math.min((i+1)*24,E.layout.spec.bays)+'</option>').join('')+'</select></label>':'';
    return '<section class="visual-panel panel" id="warehouse-visual"><div class="visual-header"><div class="visual-title"><span class="visual-title-icon">'+icon('cube')+'</span><div><h2 id="visual-heading">Tu almacén, en perspectiva</h2><p>Un espacio que puedes explorar.</p></div></div><div class="visual-header-actions">'+(props.tabs?'<div class="map-tabs" role="group" aria-label="Distribución mostrada"><button type="button" data-action="map-actual" class="'+(props.mode==='actual'?'active':'')+'" aria-pressed="'+(props.mode==='actual')+'">Actual</button><button type="button" data-action="map-propuesta" class="'+(props.mode==='propuesta'?'active':'')+'" aria-pressed="'+(props.mode==='propuesta')+'">Propuesta</button></div>':'')+'<div class="scene-view-switch" role="group" aria-label="Tipo de visualización"><button type="button" data-vaction="3d" aria-pressed="'+(lastView==='3d')+'" class="'+(lastView==='3d'?'active':'')+'">3D</button><button type="button" data-vaction="2d" aria-pressed="'+(lastView==='2d')+'" class="'+(lastView==='2d'?'active':'')+'">Plano</button></div></div></div><div class="visual-toolbar"><label class="scene-product-search">'+icon('search')+'<select id="scene-product" aria-label="Seleccionar producto en el almacén"><option value="">Buscar un producto…</option>'+E.products.map(p=>'<option value="'+p.id+'">'+esc(p.name)+' · '+esc(p.code)+'</option>').join('')+'</select></label>'+sectors+'<div class="scene-layer-controls"><label><input type="checkbox" id="scene-heat">Demanda</label><label><input type="checkbox" id="scene-connections">Conexiones</label></div></div><div class="visual-3d" '+(lastView==='2d'?'hidden':'')+'><div class="warehouse3d-stage" id="warehouse3d-stage"><div class="scene-stamp"><span></span>MODELO ILUSTRATIVO <b>'+esc(props.physical?props.physical.config.name:props.imported?'Operación importada':'W·01')+'</b></div><div class="scene-tools">'+(props.physical||props.imported?tool('overview','Ver almacén completo','reset'):'')+tool('isometric','Vista isométrica','cube')+tool('top','Vista desde arriba','top')+'<i></i>'+tool('zoom-in','Acercar almacén','plus')+tool('zoom-out','Alejar almacén','minus')+'<i></i>'+tool('expand','Ampliar almacén','expand')+'</div><div class="scene-selected" id="scene-selected" hidden></div><div class="scene-gesture">'+icon('rotate')+'<span>Arrastra para girar <b>·</b> Rueda para acercar</span></div><div class="scene-loader" id="scene-loader">Preparando tu almacén<span></span></div></div><div class="scene-family-legend"><button type="button" data-vaction="family" data-family="-1" class="active" aria-pressed="true">Todos</button>'+E.groups.map((name,i)=>'<button type="button" data-vaction="family" data-family="'+i+'" aria-pressed="false"><i style="background:var(--fam-'+i+')"></i>'+esc(name)+'</button>').join('')+'</div><div class="scene-heat-legend" hidden><span>Presencia en pedidos</span><b>0</b><i></i><b>'+Math.max(1,...counts)+'</b></div></div><div class="visual-flat" '+(lastView==='3d'?'hidden':'')+'>'+props.flat+'</div><div class="scene-player" data-playstate="idle"><div class="scene-player-row"><button type="button" class="scene-play" data-vaction="play" aria-label="Reproducir simulación">'+icon('play')+'</button><div class="scene-player-copy"><strong id="scene-play-title">Mira cómo se reorganiza.</strong><span id="scene-play-detail">Reproduce una simulación de los movimientos.</span></div><label class="scene-speed"><span class="sr-only">Velocidad de simulación</span><select id="scene-speed" aria-label="Velocidad de simulación"><option value="1">1×</option><option value="2">2×</option><option value="3">3×</option></select></label>'+tool('reset','Reiniciar simulación','reset')+'</div><div class="scene-play-progress" role="progressbar" aria-label="Avance de la simulación" aria-valuenow="0" aria-valuemin="0" aria-valuemax="100"><div id="scene-progress-fill"></div></div><div class="scene-player-note"><span>Recorrido ilustrativo</span><span>La simulación no confirma tareas</span></div></div></section>';
  }
  function mount(props,callbacks){
    const E=props.engine||window.KbitEngine;
    const panel=document.getElementById('warehouse-visual');if(!panel)return null;
    const find=selector=>panel.querySelector(selector),stage=find('#warehouse3d-stage');let expanded=false,originalOverflow='',engine,playState='idle',starting=false;
    function progress(value){find('#scene-progress-fill').style.width=(value*100)+'%';find('[role=progressbar]').setAttribute('aria-valuenow',Math.round(value*100));}
    function selection(product){const card=find('#scene-selected');find('#scene-product').value=product?product.id:'';card.hidden=!product;if(!product)return;card.innerHTML='<button type="button" class="scene-selected-close" data-vaction="clear" aria-label="Cerrar producto seleccionado">'+icon('close')+'</button><span class="scene-product-category"><i style="background:var(--fam-'+product.family+')"></i>'+esc(product.category)+'</span><h3>'+esc(product.name)+'</h3><div class="scene-selected-facts"><span>'+(props.physical?props.physical.slots[product.slot].sector+' · ':'')+E.slotName(product.slot)+'</span><span>'+product.count+' pedidos</span>'+(product.pinned?'<span>Fijo</span>':'')+'</div>'+(find('#scene-connections').checked&&product.related.length?'<div class="scene-related"><span>Se pide junto con</span>'+product.related.map(item=>'<div><span>'+esc(item.name)+'</span><b>'+item.count+'</b></div>').join('')+'</div>':'')+'<button type="button" class="scene-detail-button" data-vaction="detail" data-slot="'+product.slot+'">Ver producto '+icon('arrow')+'</button>';}
    function playback(info){playState=info.status;const player=find('.scene-player');player.dataset.playstate=info.status;const labels={idle:'Reproducir simulación',playing:'Pausar simulación',paused:'Continuar simulación',complete:'Repetir simulación',empty:'Reproducir simulación'};const play=find('[data-vaction=play]');play.innerHTML=icon(info.status==='playing'?'pause':'play');play.setAttribute('aria-label',labels[info.status]);
      const title=find('#scene-play-title'),detail=find('#scene-play-detail');
      find('.scene-player-note span').textContent=props.physical?(info.task&&Number.isFinite(info.task.routeMeters)?'Ruta por pasillos · '+new Intl.NumberFormat('es-PE',{maximumFractionDigits:1}).format(info.task.routeMeters)+' m en planta':'Menor distancia por pasillos'):'Recorrido ilustrativo';
      if(info.status==='idle'){title.textContent='Mira cómo se reorganiza.';detail.textContent='Reproduce una simulación de los movimientos.';}
      else if(info.status==='complete'){title.textContent='Cada producto, en su nuevo lugar.';detail.textContent=info.total+' movimientos visualizados · puedes volver a reproducirlos.';}
      else if(info.status==='empty'){title.textContent='No hay movimientos para simular.';detail.textContent='Prueba otras reglas en Preparar turno.';}
      else {const task=info.task;title.textContent=(task?.fromSector?task.fromSector+' · ':'')+(info.status==='paused'?'En pausa · ':'')+(props.physical&&task?'Paso '+task.id+' · ':'')+'Movimiento '+(info.step+1)+' de '+info.total;detail.textContent=task?E.products[task.product].name+' · '+E.slotName(task.from)+' → '+E.slotName(task.to)+(task.toSector&&task.toSector!==task.fromSector?' · traslado a '+task.toSector:'')+(task.temporary?' · temporal':''):'';}
      progress(info.progress||0);
    }
    try{engine=window.Kbit3D.create(stage,{...props,onSelect:selection,onPlayback:playback,onProgress:progress,onFocus:sector=>{find('.scene-stamp b').textContent=(props.physical?.config.name||'Operación importada')+(sector?' · '+sector:' · Vista general');if(props.imported&&find('#scene-sector'))find('#scene-sector').value=sector?String(Number(sector.split(' ').at(-1))-1):'-1';},getPlan:callbacks.getPlan});find('#scene-loader').remove();}catch(error){find('#scene-loader').textContent='Vista 3D no disponible. Puedes continuar con el plano.';find('#scene-loader').classList.add('scene-fallback');lastView='2d';find('[data-vaction="3d"]').disabled=true;find('[data-vaction="play"]').disabled=true;console.warn('La vista 3D no pudo iniciarse:',error.message);}
    function setView(view){lastView=view;find('.visual-3d').hidden=view==='2d';find('.visual-flat').hidden=view==='3d';panel.querySelectorAll('.scene-view-switch button').forEach(button=>{const active=button.dataset.vaction===view;button.classList.toggle('active',active);button.setAttribute('aria-pressed',active);});find('.scene-product-search').hidden=view==='2d';find('.scene-layer-controls').hidden=view==='2d';if(find('#scene-sector'))find('#scene-sector').parentElement.hidden=view==='2d';engine?.resize();}
    async function play(){if(!engine||starting){if(!engine)callbacks.toast('La vista 3D no está disponible en este navegador. Puedes continuar con el plano.');return;}setView('3d');try{engine?.setCategory(-1);panel.querySelectorAll('[data-family]').forEach(item=>{const all=item.dataset.family==='-1';item.classList.toggle('active',all);item.setAttribute('aria-pressed',all);});find('#scene-connections').checked=false;engine?.setConnections(false);if(playState==='playing'||playState==='paused')engine.play();else{starting=true;find('#scene-play-title').textContent='Preparando los movimientos…';const plan=await callbacks.getPlan();if(panel.isConnected)engine.play(plan);}}catch(error){callbacks.toast(error.message);}finally{starting=false;}}
    function expand(){expanded=!expanded;panel.classList.toggle('is-expanded',expanded);if(expanded){originalOverflow=document.body.style.overflow;document.body.style.overflow='hidden';}else document.body.style.overflow=originalOverflow;find('[data-vaction=expand]').setAttribute('aria-label',expanded?'Cerrar almacén ampliado':'Ampliar almacén');find('[data-vaction=expand]').title=expanded?'Cerrar almacén ampliado':'Ampliar almacén';find('[data-vaction=expand]').innerHTML=icon(expanded?'close':'expand');engine?.resize();}
    const click=event=>{const button=event.target.closest('[data-vaction]');if(!button)return;const action=button.dataset.vaction;
      if(action==='overview')return engine?.focusAll();if(action==='3d'||action==='2d')return setView(action);if(action==='play')return play();if(action==='reset')return engine?.stop();if(action==='clear')return engine?.select(-1);if(action==='detail')return callbacks.onSlot(Number(button.dataset.slot));if(action==='expand')return expand();if(action==='zoom-in'||action==='zoom-out')return engine?.zoom(action==='zoom-in'?1.2:1/1.2);if(action==='isometric'||action==='top')return engine?.preset(action);
      if(action==='family'){const id=Number(button.dataset.family);engine?.setCategory(id);panel.querySelectorAll('[data-family]').forEach(item=>{const active=Number(item.dataset.family)===id;item.classList.toggle('active',active);item.setAttribute('aria-pressed',active);});}
    };
    panel.addEventListener('click',click);find('#scene-product').addEventListener('change',event=>engine?.select(event.target.value===''?-1:Number(event.target.value)));find('#scene-heat').addEventListener('change',event=>{const active=event.target.checked;engine?.setHeat(active);find('.scene-family-legend').hidden=active;find('.scene-heat-legend').hidden=!active;engine?.setCategory(-1);panel.querySelectorAll('[data-family]').forEach(item=>{const all=item.dataset.family==='-1';item.classList.toggle('active',all);item.setAttribute('aria-pressed',all);});});find('#scene-connections').addEventListener('change',event=>{engine?.setConnections(event.target.checked);if(event.target.checked&&find('#scene-product').value==='')engine?.select(0);});find('#scene-speed').addEventListener('change',event=>engine?.setSpeed(Number(event.target.value)));
    find('#scene-sector')?.addEventListener('change',event=>engine?.focusSector(Number(event.target.value)));
    const escapeKey=event=>{if(event.key==='Escape'&&expanded)expand();};document.addEventListener('keydown',escapeKey);
    setView(lastView);
    return {play,destroy(){if(expanded)document.body.style.overflow=originalOverflow;panel.removeEventListener('click',click);document.removeEventListener('keydown',escapeKey);engine?.destroy();}};
  }
  window.KbitVisual={panel,mount};
})();
